-- Human-verified operating expense ledger. No tax or accounting treatment is inferred.
begin;
create table public.operating_expenses(id uuid primary key default gen_random_uuid(),company_id uuid not null,asset_id uuid,category text not null check(category in('fuel','maintenance','insurance','tolls','permits','parking','factoring','software','payroll','other')),incurred_on date not null,amount_cents bigint not null check(amount_cents>0),vendor text,source_reference text,factual_note text not null check(char_length(factual_note)between 3 and 2000),status text not null default 'active' check(status in('active','voided')),verified_by uuid not null,request_id text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,id),unique(company_id,request_id),constraint expense_asset_company_fk foreign key(company_id,asset_id)references public.fleet_assets(company_id,id));
create table public.operating_expense_events(id uuid primary key default gen_random_uuid(),company_id uuid not null,expense_id uuid not null,event_type text not null check(event_type in('recorded','voided')),factual_note text not null,actor_user_id uuid not null,request_id text not null,created_at timestamptz not null default now(),unique(company_id,request_id),constraint expense_event_fk foreign key(company_id,expense_id)references public.operating_expenses(company_id,id));
alter table public.operating_expenses enable row level security;alter table public.operating_expense_events enable row level security;create policy expenses_finance_select on public.operating_expenses for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','accounting'));create policy expense_events_finance_select on public.operating_expense_events for select using(company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','accounting'));
revoke all privileges on table public.operating_expenses,public.operating_expense_events from public,anon,authenticated,service_role;grant select on table public.operating_expenses,public.operating_expense_events to authenticated,service_role;grant insert,update on table public.operating_expenses to service_role;grant insert on table public.operating_expense_events to service_role;
create or replace function public.list_verified_operating_expenses()returns table(id uuid,asset_id uuid,unit_number text,category text,incurred_on date,amount_cents bigint,vendor text,source_reference text,factual_note text,status text,created_at timestamptz)language sql stable security definer set search_path=public as $$select e.id,e.asset_id,a.unit_number,e.category,e.incurred_on,e.amount_cents,e.vendor,e.source_reference,e.factual_note,e.status,e.created_at from public.operating_expenses e left join public.fleet_assets a on a.company_id=e.company_id and a.id=e.asset_id where e.company_id=public.document_intake_company_id()and public.current_business_role()in('super_admin','owner','accounting')order by e.incurred_on desc,e.created_at desc$$;
create or replace function public.record_verified_operating_expense(p_asset_id uuid,p_category text,p_incurred_on date,p_amount_cents bigint,p_vendor text,p_source_reference text,p_note text,p_request_id text)returns uuid language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;begin if c is null or u is null or r not in('super_admin','owner','accounting')then raise exception 'Not authorized';end if;if p_request_id is null or char_length(p_request_id)not between 8 and 200 or p_category not in('fuel','maintenance','insurance','tolls','permits','parking','factoring','software','payroll','other')or p_incurred_on is null or p_incurred_on>current_date+1 or p_amount_cents is null or p_amount_cents<=0 or p_note is null or char_length(trim(p_note))not between 3 and 2000 then raise exception 'Invalid expense facts';end if;select id into x from public.operating_expenses where company_id=c and request_id=p_request_id;if x is not null then return x;end if;if p_asset_id is not null and not exists(select 1 from public.fleet_assets where company_id=c and id=p_asset_id)then raise exception 'Same-company asset not found';end if;insert into public.operating_expenses(company_id,asset_id,category,incurred_on,amount_cents,vendor,source_reference,factual_note,verified_by,request_id)values(c,p_asset_id,p_category,p_incurred_on,p_amount_cents,nullif(trim(p_vendor),''),nullif(trim(p_source_reference),''),trim(p_note),u,p_request_id)returning id into x;insert into public.operating_expense_events(company_id,expense_id,event_type,factual_note,actor_user_id,request_id)values(c,x,'recorded',trim(p_note),u,p_request_id||':recorded');return x;end$$;
create or replace function public.void_verified_operating_expense(p_expense_id uuid,p_reason text,p_request_id text)returns uuid language plpgsql security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();u uuid:=auth.uid();r text:=public.current_business_role();x uuid;begin if c is null or u is null or r not in('super_admin','owner','accounting')then raise exception 'Not authorized';end if;if p_reason is null or char_length(trim(p_reason))not between 3 and 2000 or p_request_id is null or char_length(p_request_id)not between 8 and 200 then raise exception 'Reason required';end if;select expense_id into x from public.operating_expense_events where company_id=c and request_id=p_request_id;if x is not null then return x;end if;update public.operating_expenses set status='voided',updated_at=now()where company_id=c and id=p_expense_id and status='active'returning id into x;if x is null then raise exception 'Active expense not found';end if;insert into public.operating_expense_events(company_id,expense_id,event_type,factual_note,actor_user_id,request_id)values(c,x,'voided',trim(p_reason),u,p_request_id);return x;end$$;
revoke all on function public.list_verified_operating_expenses(),public.record_verified_operating_expense(uuid,text,date,bigint,text,text,text,text),public.void_verified_operating_expense(uuid,text,text)from public,anon;grant execute on function public.list_verified_operating_expenses(),public.record_verified_operating_expense(uuid,text,date,bigint,text,text,text,text),public.void_verified_operating_expense(uuid,text,text)to authenticated;commit;
